        if (der[ptr.header()] != 0x03) revert InvalidAsn1Type();
        if (ptr.length() == 0) revert InvalidAsn1Length();

        uint256 unusedBits = uint8(der[ptr.content()]);
        if (unusedBits > 7) revert InvalidAsn1Value();

        uint256 len = ptr.length() - 1;
